sys_script_include.script:
var RsvpUtils = Class.create();
RsvpUtils.prototype = {
    initialize: function() {},

    refQualTask7: function() {
        var rsvpNotToBeShown = [];
        var grRsvpList = new GlideRecord('x_1488662_rsvp_t_0_course_enrollments');
        grRsvpList.addQuery("opened_by", gs.getUserID()); // Treinamentos que o usuário já está cadastrado
        grRsvpList.addQuery("course_day", '!=', ""); // Evita registros sem data
        grRsvpList.query();

        while (grRsvpList.next()) {
            rsvpNotToBeShown.push(grRsvpList.course_day.toString()); // Armazena os `course_day`
            // rsvpNotToBeShown.push(grRsvpList.course_name.toString()); // Armazena os `course_day`
        }

        var rsvpToBeShown = [];
        var grSchedule = new GlideRecord("x_1488662_rsvp_t_0_training_schedules");
        grSchedule.query('max_capacity_reached', 'False'); // Filtra os treinamentos que ainda tem vagas
        // Filtra para pegar apenas cursos que o usuário ainda pode se inscrever
		grSchedule.query('dead_line_reached', 'False');
        grSchedule.query();

        while (grSchedule.next()) {
            var scheduleDay = grSchedule.course_day.toString(); // Pegando o mesmo campo usado na verificação
            if (rsvpNotToBeShown.indexOf(scheduleDay) === -1) {
                rsvpToBeShown.push(grSchedule.getUniqueValue());
            }
        }

        return "sys_idIN" + rsvpToBeShown.join(",");
    },

    type: 'RsvpUtils'
};
